// =================================================================
//  CLIENT-CONFIG.JS — Configuration du CLIENT FINAL (partagé)
//
//  Permet de choisir pour qui l'intervention est réalisée :
//   • Bouygues Telecom   (par défaut — comportement historique)
//   • Bretagne Telecom   (btblue)
//
//  ⚠️  Le logo IPKONEKT ne change JAMAIS, quel que soit le client.
//      Seuls le 2e logo (en-tête Word), le bandeau de titre et le
//      pied de page "Document confidentiel..." s'adaptent.
//
//  Utilisé par : 4g-5g/app.js, starlink/app.js, pico-quatra/app.js,
//  4g-5g/pdfReport.js. Doit être chargé AVANT ces scripts.
//
//  Chaque formulaire contient un <select id="client_final"> :
//      <option value="bouygues">Bouygues Telecom</option>
//      <option value="bretagne">Bretagne Telecom</option>
// =================================================================

// Logo Bretagne Telecom (btblue) — PNG fond transparent, 420×133 px
// (ratio largeur/hauteur ≈ 3.15 : logo LARGE, ne pas afficher en carré !)
const LOGO_BTBLUE_B64 = "";

// Logo IEC Telecom — PNG fond transparent, 490×125 px
// (ratio largeur/hauteur ≈ 3.92 : logo LARGE, ne pas afficher en carré !)
const LOGO_IECTELECOM_B64 = "";

// -----------------------------------------------------------------
//  Référentiel des clients finaux
//  logoRatio = largeur / hauteur du logo source (pour ne pas l'étirer)
// -----------------------------------------------------------------
const CLIENTS_FINAUX = {
    bouygues: {
        id: "bouygues",
        label: "Bouygues Telecom",
        // le logo Bouygues est défini dans logos.js de chaque formulaire
        getLogoB64: () => (typeof LOGO_BOUYGUES_B64 !== "undefined" ? LOGO_BOUYGUES_B64 : ""),
        logoRatio: 1.0   // logo carré (128×127)
    },
    bretagne: {
        id: "bretagne",
        label: "Bretagne Telecom",
        getLogoB64: () => LOGO_BTBLUE_B64,
        logoRatio: 420 / 133  // ≈ 3.15 — logo large
    },
    bluewireless: {
        id: "bluewireless",
        label: "Bluewireless",
        // Logo défini dans starlink/logos.js (projet STARLINK)
        getLogoB64: () => (typeof LOGO_BLUEWIRELESS_B64 !== "undefined" ? LOGO_BLUEWIRELESS_B64 : ""),
        logoRatio: 290 / 202  // ≈ 1.44
    },
    iectelecom: {
        id: "iectelecom",
        label: "IEC Telecom",
        getLogoB64: () => LOGO_IECTELECOM_B64,
        logoRatio: 490 / 125  // ≈ 3.92 — logo large
    },
    // Clients ajoutés pour le formulaire CÂBLAGE.
    // Les logos sont définis dans cablage/logos.js ; le typeof évite une
    // erreur dans les autres formulaires qui ne chargent pas ces constantes.
    emag: {
        id: "emag",
        label: "E-Mag numérique",
        getLogoB64: () => (typeof LOGO_EMAG_B64 !== "undefined" ? LOGO_EMAG_B64 : ""),
        logoRatio: 460 / 164  // ≈ 2.80
    },
    etam: {
        id: "etam",
        label: "ETAM Lingerie",
        getLogoB64: () => (typeof LOGO_ETAM_B64 !== "undefined" ? LOGO_ETAM_B64 : ""),
        logoRatio: 703 / 194  // ≈ 3.62 — logo large
    }
};

// -----------------------------------------------------------------
//  Lit le <select id="client_final"> du formulaire courant.
//  Retourne TOUJOURS un client valide (bouygues par défaut), donc
//  les anciens JSON sans champ client restent 100 % compatibles.
// -----------------------------------------------------------------
function getClientFinal() {
    const sel = document.getElementById("client_final");
    const key = sel && sel.value ? sel.value : "bouygues";
    return CLIENTS_FINAUX[key] || CLIENTS_FINAUX.bouygues;
}

// -----------------------------------------------------------------
//  Helpers d'affichage
// -----------------------------------------------------------------

// Texte du pied de page Word/PDF
function clientFooterText() {
    return "Document confidentiel — Usage interne IPKONEKT / " + getClientFinal().label;
}

// Texte du bandeau de titre ("Bouygues Telecom │ IPKONEKT", etc.)
function clientBannerText(separator) {
    return getClientFinal().label + " " + (separator || "│") + " IPKONEKT";
}

// Dimensions du logo client pour le docx, à HAUTEUR visuelle équivalente.
// targetHeight = hauteur (pt) qu'aurait un logo carré à cet emplacement.
// Pour un logo large (Bretagne), on réduit un peu la hauteur pour garder
// un poids visuel comparable, et on calcule la largeur via le ratio.
function clientLogoSize(targetHeight) {
    const c = getClientFinal();
    if (c.logoRatio <= 1.5) {
        // logo ± carré (ou légèrement large, ex. Bluewireless ≈1.44) → on garde la hauteur cible
        return { width: Math.round(targetHeight * c.logoRatio), height: targetHeight };
    }
    // logo large → hauteur réduite (~60 %) pour un rendu équilibré
    const h = Math.round(targetHeight * 0.6);
    return { width: Math.round(h * c.logoRatio), height: h };
}

// Octets du logo client (Uint8Array) pour ImageRun — réutilise le
// convertisseur b64ToUint8Array défini dans logos.js de chaque dossier.
function clientLogoBytes() {
    const b64 = getClientFinal().getLogoB64();
    if (!b64) return null;
    const bin = atob(b64);
    const bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
    return bytes;
}
